import { useId } from 'react';
import './WorkspaceViewChoice.css';
export type WorkspaceView = 'board' | 'list' | 'timeline';
export type WorkspaceAction = { type: 'workspace/viewChanged'; value: WorkspaceView };
export function WorkspaceViewChoice({ value, dispatch }: { value: WorkspaceView; dispatch: (action: WorkspaceAction) => void }) {
  const name = useId();
  return <fieldset className="view-choice"><legend className="visually-hidden">Workspace view</legend>
    {(['board', 'list', 'timeline'] as const).map(option => <label key={option}>
      <input type="radio" name={name} value={option} checked={value === option} onChange={() => dispatch({ type: 'workspace/viewChanged', value: option })} />
      <span>{option[0].toUpperCase() + option.slice(1)}</span>
    </label>)}
  </fieldset>;
}

