.view-choice {display:inline-flex;gap:2px;margin:0;padding:3px;border:1px solid #727681;border-radius:8px;min-width:0}
.view-choice label {position:relative;cursor:pointer}
.view-choice input,.visually-hidden {position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
.view-choice span {display:block;padding:5px 10px;border-radius:5px;font:inherit}
.view-choice input:checked + span {background:#25365e;color:white;font-weight:700}
.view-choice input:focus-visible + span {outline:2px solid #255ec9;outline-offset:2px}
@media (forced-colors:active){.view-choice input:checked + span{outline:2px solid Highlight}}
